{"CommandLine":"$results = @()
$cDirs = Get-ChildItem -Path "C:\" -Directory -Force -ErrorAction SilentlyContinue
foreach ($d in $cDirs) {
    if ($d.Name -in @('$Recycle.Bin', 'System Volume Information')) {
        continue
    }
    try {
        $size = (Get-ChildItem -Path $d.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        $results += [PSCustomObject]@{
            Folder = $d.FullName
            SizeGB = [math]::Round($size / 1GB, 2)
        }
    } catch {}
}
$results | Sort-Object SizeGB -Descending | Format-Table -AutoSize
